<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Snake Game</title>
  <style>
    body {
      margin: 0;
      background-color: #111;
      color: white;
      font-family: sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
    }
    #container {
      text-align: center;
    }
    canvas {
      border: 1px solid #555;
      background-color: #222;
    }
    #controls {
      margin-top: 20px;
    }
    button {
      margin: 5px;
      padding: 10px 20px;
      font-size: 16px;
      cursor: pointer;
    }
    #score {
      margin-top: 10px;
      font-size: 20px;
    }
  </style>
</head>
<body>
  <div id="container">
    <canvas id="snake"></canvas>
    <div id="controls">
      <button id="start">Start</button>
      <button id="pause">Pause</button>
      <button id="reset">Reset</button>
      <div id="score">Score: 0</div>
    </div>
  </div>
  <script>
    const canvas = document.getElementById('snake');
    const ctx = canvas.getContext('2d');

    canvas.width = 400;
    canvas.height = 400;

    window.addEventListener('load', () => {
      // Initialize game object
      window.game = {
        w: 20,
        h: 20,
        cellSize: 20, // since canvas is 400x400 and 20 cells per side
        snakeArr: [],
        direction: 'right',
        foodX: 0,
        foodY: 0,
        scoreVal: 0,
        aliveStatus: false,

        reset() {
          this.snakeArr = [
            [10, 10],
            [9, 10],
            [8, 10]
          ];
          this.direction = 'right';
          this.scoreVal = 0;
          this.aliveStatus = true;
          this.generateFood();
          this.draw();
        },

        generateFood() {
          let newFoodX, newFoodY;
          do {
            newFoodX = Math.floor(Math.random() * this.w);
            newFoodY = Math.floor(Math.random() * this.h);
          } while (this.snakeArr.some(segment => segment[0] === newFoodX && segment[1] === newFoodY));
          this.foodX = newFoodX;
          this.foodY = newFoodY;
        },

        tick() {
          if (!this.aliveStatus) return;

          const head = [...this.snakeArr[0]];
          let newHead = [...head];

          switch (this.direction) {
            case 'up':
              newHead[1] -= 1;
              break;
            case 'down':
              newHead[1] += 1;
              break;
            case 'left':
              newHead[0] -= 1;
              break;
            case 'right':
              newHead[0] += 1;
              break;
          }

          // Check wall collision
          if (newHead[0] < 0 || newHead[0] >= this.w ||
              newHead[1] < 0 || newHead[1] >= this.h) {
            this.aliveStatus = false;
            return;
          }

          // Check self collision
          const restOfBody = this.snakeArr.slice(1);
          if (restOfBody.some(segment => segment[0] === newHead[0] && segment[1] === newHead[1])) {
            this.aliveStatus = false;
            return;
          }

          // Add new head to the front
          this.snakeArr.unshift(newHead);

          // Check for food collision
          if (newHead[0] === this.foodX && newHead[1] === this.foodY) {
            this.scoreVal += 1;
            this.generateFood();
            // Do not remove tail, so snake grows next step? No: when you eat, the next movement adds a new head and keeps the tail. So in this case, we do not pop.
          } else {
            // Remove the last element
            this.snakeArr.pop();
          }

          this.draw();
        },

        draw() {
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          const cellSize = this.cellSize;
          // Draw snake
          ctx.fillStyle = 'lime';
          for (const [x, y] of this.snakeArr) {
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
          }

          // Draw food
          ctx.fillStyle = 'red';
          const fx = this.foodX * cellSize;
          const fy = this.foodY * cellSize;
          ctx.fillRect(fx, fy, cellSize, cellSize);

          document.getElementById('score').textContent = `Score: ${this.scoreVal}`;
        },

        setDir(dir) {
          // Check if direction is opposite
          const current = this.direction;
          if ((current === 'up' && dir === 'down') ||
              (current === 'down' && dir === 'up') ||
              (current === 'left' && dir === 'right') ||
              (current === 'right' && dir === 'left')) {
            return; // reverse, ignore
          }
          this.direction = dir;
        },

        setFood(x, y) {
          this.foodX = x;
          this.foodY = y;
          this.draw();
        },

        snake() {
          return [...this.snakeArr];
        },

        food() {
          return [this.foodX, this.foodY];
        },

        alive() {
          return this.aliveStatus;
        },

        score() {
          return this.scoreVal;
        }
      };

      // Initialize game on load
      window.game.reset();

      let gameInterval = null;

      document.getElementById('start').addEventListener('click', () => {
        if (!gameInterval) {
          gameInterval = setInterval(() => window.game.tick(), 150); // adjust speed as needed, maybe 150ms per tick for playability
        }
      });

      document.getElementById('pause').addEventListener('click', () => {
        clearInterval(gameInterval);
        gameInterval = null;
      });

      document.getElementById('reset').addEventListener('click', () => {
        window.game.reset();
        clearInterval(gameInterval);
        gameInterval = null;
      });

      // Handle keyboard input
      window.addEventListener('keydown', (e) => {
        switch(e.key) {
          case 'ArrowUp':
            window.game.setDir('up');
            break;
          case 'ArrowDown':
            window.game.setDir('down');
            break;
          case 'ArrowLeft':
            window.game.setDir('left');
            break;
          case 'ArrowRight':
            window.game.setDir('right');
            break;
        }
      });
    });
  </script>
</body>
</html>
